'use client'; import { useCallback, useEffect, useMemo, useState } from 'react'; import { VendorFeedbackBanner, useVendorFeedback } from '@/components/vendor/ui/useVendorFeedback';
import { VendorDataTable } from '@/components/vendor/ui/VendorDataTable';
import { VendorModuleHeader, VendorStatusPill } from '@/components/vendor/ui/VendorModuleHeader';
import { vendorFieldClass, vendorLabelClass, VendorModal } from '@/components/vendor/ui/VendorModal';
import { supabase } from '@/lib/supabaseClient';
