import { DEFAULT_VENDOR_ID } from '@/lib/vendor-supabase/constants';
import type { InvoiceRow, PurchaseOrderRow } from '@/lib/vendor-supabase/types'; type UploadInvoiceForm = { invoice_number: string; po_id: string; file_url: string; subtotal: string;
}; const emptyUpload: UploadInvoiceForm = { invoice_number: '', po_id: '', file_url: '', subtotal: '' }; const INVOICE_PO_STATUSES = ['ACCEPTED', 'PARTIAL', 'COMPLETED'] as const; function formatInr(n: number) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(n);
} function invoicePoMeta(row: InvoiceRow) { const po = row.purchase_orders; const single = Array.isArray(po) ? po[0] : po; return { poNumber: single?.po_number ?? row.po_id?.slice(0, 8) ?? '—', hospital: single?.hospital_name ?? '—', };
} function paymentTone(status: string) { const s = status.toUpperCase(); if (s === 'PAID' || s === 'APPROVED') return 'success' as const; if (s === 'OVERDUE') return 'danger' as const; return 'warning' as const;
} function InvoicesWorkspace() { const { feedback, showSuccess, showError } = useVendorFeedback(); const [invoices, setInvoices] = useState<InvoiceRow[]>([]); const [invoicesLoading, setInvoicesLoading] = useState(true); const [allOrders, setAllOrders] = useState<PurchaseOrderRow[]>([]); const [generateModalOrders, setGenerateModalOrders] = useState<PurchaseOrderRow[]>([]); const [poModalLoading, setPoModalLoading] = useState(false); const [uploadOpen, setUploadOpen] = useState(false); const [generateOpen, setGenerateOpen] = useState(false); const [selectedPoId, setSelectedPoId] = useState(''); const [uploadForm, setUploadForm] = useState<UploadInvoiceForm>(emptyUpload); const [isSubmitting, setIsSubmitting] = useState(false); const loadInvoices = useCallback(async () => { setInvoicesLoading(true); try { const { data, error } = await supabase .from('invoices') .select('id, invoice_number, po_id, vendor_id, subtotal, tax_amount, total_amount, status, due_date, purchase_orders(po_number, hospital_name)') .eq('vendor_id', DEFAULT_VENDOR_ID) .order('created_at', { ascending: false }); if (error) { showError(error.message); setInvoices([]); } else { setInvoices((data as InvoiceRow[]) ?? []); } } catch (e) { showError(e instanceof Error ? e.message : 'Failed to load invoices'); setInvoices([]); } setInvoicesLoading(false); }, [showError]); const loadAllOrders = useCallback(async () => { try { const { data } = await supabase .from('purchase_orders') .select('*') .eq('vendor_id', DEFAULT_VENDOR_ID) .order('created_at', { ascending: false }); if (data) setAllOrders((data as PurchaseOrderRow[]) ?? []); } catch { /* upload modal PO list is optional */ } }, []); useEffect(() => { void loadInvoices(); void loadAllOrders(); }, [loadInvoices, loadAllOrders]); useEffect(() => { if (!generateOpen) return; let cancelled = false; void (async () => { setPoModalLoading(true); try { const { data, error } = await supabase .from('purchase_orders') .select('*') .eq('vendor_id', DEFAULT_VENDOR_ID) .in('status', [...INVOICE_PO_STATUSES]) .order('created_at', { ascending: false }); if (error) { showError(error.message); if (!cancelled) setGenerateModalOrders([]); return; } const rows = (data as PurchaseOrderRow[]) ?? []; if (!cancelled) { setGenerateModalOrders(rows); setSelectedPoId(rows[0]?.id ?? ''); } } catch (e) { showError(e instanceof Error ? e.message : 'Failed to load purchase orders'); if (!cancelled) setGenerateModalOrders([]); } finally { if (!cancelled) setPoModalLoading(false); } })(); return () => { cancelled = true; }; }, [generateOpen, showError]); const selectedPo = useMemo( () => generateModalOrders.find((o) => o.id === selectedPoId) ?? null, [generateModalOrders, selectedPoId], ); const invoicePreview = useMemo(() => { if (!selectedPo) return null; const subtotal = Number(selectedPo.total_amount); if (!Number.isFinite(subtotal)) return null; const tax_amount = subtotal * 0.18; return { subtotal, tax_amount, total_amount: subtotal + tax_amount }; }, [selectedPo]); const openGenerate = () => { setGenerateOpen(true); }; const openUpload = () => { setUploadForm({ ...emptyUpload, po_id: allOrders[0]?.id ?? '' }); setUploadOpen(true); }; const handleGenerateFromPo = async () => { if (!selectedPo || !invoicePreview) return; setIsSubmitting(true); try { const due = new Date(); due.setDate(due.getDate() + 30); const { error } = await supabase.from('invoices').insert([ { invoice_number: `INV-${Date.now()}`, po_id: selectedPo.id, vendor_id: DEFAULT_VENDOR_ID, subtotal: invoicePreview.subtotal, tax_amount: invoicePreview.tax_amount, total_amount: invoicePreview.total_amount, status: 'SUBMITTED', due_date: due.toISOString().slice(0, 10), }, ]); if (error) { showError(error.message); window.alert(`Error: ${error.message}`); return; } showSuccess('Invoice generated from PO and submitted.'); setGenerateOpen(false); await loadInvoices(); } catch (e) { showError(e instanceof Error ? e.message : 'Failed to insert invoice'); } finally { setIsSubmitting(false); } }; const handleUploadInvoice = async (e: React.FormEvent) => { e.preventDefault(); const subtotal = Number(uploadForm.subtotal); if (!Number.isFinite(subtotal) || subtotal <= 0) { window.alert('Enter a valid subtotal.'); return; } setIsSubmitting(true); try { const tax_amount = subtotal * 0.18; const due = new Date(); due.setDate(due.getDate() + 30); const { error } = await supabase.from('invoices').insert([ { invoice_number: uploadForm.invoice_number.trim() || `EXT-${Date.now()}`, po_id: uploadForm.po_id || null, vendor_id: DEFAULT_VENDOR_ID, subtotal, tax_amount, total_amount: subtotal + tax_amount, status: 'SUBMITTED', due_date: due.toISOString().slice(0, 10), file_url: uploadForm.file_url.trim() || null, }, ]); if (error) { showError(error.message); window.alert(`Error: ${error.message}`); return; } showSuccess('External invoice uploaded.'); setUploadOpen(false); setUploadForm(emptyUpload); await loadInvoices(); } catch (err) { showError(err instanceof Error ? err.message : 'Upload failed'); } finally { setIsSubmitting(false); } }; const handleDownloadAdvice = () => { const rows = ['Reference,Amount,Status', ...MOCK_CREDIT_NOTES.map((c) => `${c.reference},${c.amount},${c.status}`)]; const blob = new Blob([rows.join('\n')], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'payment_advice.csv'; link.click(); URL.revokeObjectURL(url); showSuccess('Payment advice downloaded.'); }; return ( <div className="space-y-6"> <VendorModuleHeader title="Invoices & Payments" description="Auto-invoice from PO/delivery, GST breakdown, payment tracker, credit/debit notes." actions={ <> <button type="button" onClick={openUpload} className="rounded-xl border border-vendor-accent/20 px-4 py-2 text-xs font-bold " > Upload invoice </button> <button type="button" onClick={openGenerate} className="rounded-xl bg-vendor-secondary px-4 py-2 text-xs font-bold text-white hover:opacity-90"> Generate from PO </button> </> } /> <VendorFeedbackBanner feedback={feedback} /> {invoicesLoading ? ( <p className="text-sm text-vendor-muted">Loading invoices…</p> ) : ( <VendorDataTable<InvoiceRow> rows={invoices} rowKey={(i) => i.id} columns={[ { key: 'id', header: 'Invoice', render: (i) => <span className="font-mono font-bold">{i.invoice_number ?? i.id.slice(0, 8)}</span>, }, { key: 'po', header: 'PO', render: (i) => invoicePoMeta(i).poNumber, }, { key: 'hospital', header: 'Hospital', render: (i) => invoicePoMeta(i).hospital, }, { key: 'gst', header: 'Tax (GST)', render: (i) => ( <span className="text-xs font-mono"> {i.tax_amount != null ? formatInr(Number(i.tax_amount)) : '—'} (18%) </span> ), }, { key: 'total', header: 'Total', render: (i) => <span className="font-mono font-bold">{formatInr(Number(i.total_amount))}</span>, }, { key: 'status', header: 'Payment', render: (i) => <VendorStatusPill label={i.status} tone={paymentTone(i.status)} />, }, ]} /> )} <section className="rounded-2xl border border-vendor-accent/20 bg-vendor-card p-5 border-vendor-accent/20 bg-vendor-card"> <h2 className="text-sm font-black">Credit / debit notes</h2> <ul className="mt-3 space-y-2"> {MOCK_CREDIT_NOTES.map((cn) => ( <li key={cn.id} className="flex flex-wrap justify-between gap-2 rounded-lg border border-slate-100 px-3 py-2 text-sm "> <span className="font-mono font-bold">{cn.reference}</span> <span>{cn.reason}</span> <span className="font-bold">₹{cn.amount.toLocaleString('en-IN')}</span> <VendorStatusPill label={cn.status} tone="info" /> </li> ))} </ul> <button type="button" onClick={handleDownloadAdvice} className="mt-3 text-xs font-bold text-vendor-secondary "> Download payment advice PDF </button> </section> <VendorModal title="Generate invoice from PO" open={generateOpen} onClose={() => setGenerateOpen(false)} footer={ <> <button type="button" onClick={() => setGenerateOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Cancel </button> <button type="button" disabled={isSubmitting || !invoicePreview || poModalLoading} onClick={() => void handleGenerateFromPo()} className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white disabled:opacity-60" > {isSubmitting ? 'Submitting…' : 'Insert invoice'} </button> </> } > {poModalLoading ? ( <p className="text-sm text-vendor-muted">Loading purchase orders…</p> ) : generateModalOrders.length === 0 ? ( <p className="text-sm text-vendor-muted">No eligible POs (ACCEPTED, PARTIAL, or COMPLETED).</p> ) : ( <> <label className={vendorLabelClass}> Purchase order <select value={selectedPoId} onChange={(e) => setSelectedPoId(e.target.value)} className={vendorFieldClass} > {generateModalOrders.map((o) => ( <option key={o.id} value={o.id}> {o.po_number} · {o.hospital_name} · {formatInr(Number(o.total_amount))} </option> ))} </select> </label> {invoicePreview ? ( <dl className="mt-4 space-y-2 text-sm"> <div className="flex justify-between"> <dt>Subtotal</dt> <dd className="font-mono font-bold">{formatInr(invoicePreview.subtotal)}</dd> </div> <div className="flex justify-between"> <dt>GST tax (18%)</dt> <dd className="font-mono font-bold">{formatInr(invoicePreview.tax_amount)}</dd> </div> <div className="flex justify-between border-t border-slate-200 pt-2 font-black border-vendor-accent/20"> <dt>Final total</dt> <dd className="font-mono text-vendor-secondary ">{formatInr(invoicePreview.total_amount)}</dd> </div> </dl> ) : null} </> )} </VendorModal> <VendorModal title="Upload external invoice" open={uploadOpen} onClose={() => setUploadOpen(false)} footer={ <> <button type="button" onClick={() => setUploadOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Cancel </button> <button type="submit" form="upload-invoice-form" disabled={isSubmitting} className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white disabled:opacity-60" > {isSubmitting ? 'Uploading…' : 'Save invoice'} </button> </> } > <form id="upload-invoice-form" onSubmit={(e) => void handleUploadInvoice(e)} className="space-y-3"> <label className={vendorLabelClass}> Invoice number <input value={uploadForm.invoice_number} onChange={(e) => setUploadForm((f) => ({ ...f, invoice_number: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> Linked PO (optional) <select value={uploadForm.po_id} onChange={(e) => setUploadForm((f) => ({ ...f, po_id: e.target.value }))} className={vendorFieldClass} > <option value="">None</option> {allOrders.map((o) => ( <option key={o.id} value={o.id}> {o.po_number} </option> ))} </select> </label> <label className={vendorLabelClass}> Subtotal (INR) <input required type="number" min={1} value={uploadForm.subtotal} onChange={(e) => setUploadForm((f) => ({ ...f, subtotal: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> PDF / document URL <input type="url" value={uploadForm.file_url} onChange={(e) => setUploadForm((f) => ({ ...f, file_url: e.target.value }))} placeholder="https://…" className={vendorFieldClass} /> </label> </form> </VendorModal> </div> );
}

export default InvoicesWorkspace;
export { InvoicesWorkspace };
